package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ClassUtils_toClass_TriageGen1Test {





    @Test
    public void testToClass_ValidObjects() {
        Object[] input = new Object[]{"string", 123, 45.67, true};
        Class<?>[] expected = new Class<?>[]{
                String.class,
                Integer.class,
                Double.class,
                Boolean.class
        };
        Class<?>[] result = ClassUtils.toClass(input);
        assertArrayEquals("Should return an array of classes corresponding to the object types", expected, result);
    }




}

