public class ClassUtils_toClass_TriageGen1Test {







    @Test
    public void testToClass_ArrayWithNullElements() {
        Object[] input = new Object[]{"hello", null, 10};
        Class<?>[] expected = new Class<?>[]{
                String.class,
                null,
                Integer.class
        };
        Class<?>[] result = ClassUtils.toClass(input);
        assertArrayEquals("Null elements in input array should result in null elements in the class array", expected, result);
    }


}

